    if not woman_patches:
        return "No woman found in the image."

    woman_patch = woman_patches[0]
    description = woman_patch.simple_query()

    if "woman" in description.lower():
        return f"The image contains a woman described as: {description}"

    gender_info = woman_patch.llm_query(f"What is the gender of the person in the image?", long_answer=False)

    if "woman" in gender_info.lower():
        return f"The image contains a woman described as: {description}"
    elif "man" in gender_info.lower():
        return f"The image does not contain a woman, but rather a man described as: {description}"
    else:
        return f"The image contains a person described as: {description}, but I couldn't determine their gender."

